describe('addUsage', () => {
  const a = {inputTokens: 1, outputTokens: 2, totalTokens: 3};
  const b = {inputTokens: 10, outputTokens: 20, totalTokens: 30};

  it('sums each token field when both rounds reported', () => {
    expect(addUsage(a, b)).toEqual({inputTokens: 11, outputTokens: 22, totalTokens: 33});
  });

  it('keeps the reported side when the other round reported nothing', () => {
    expect(addUsage(undefined, b)).toEqual(b);
    expect(addUsage(a, undefined)).toEqual(a);
  });

  it('stays undefined when neither round reported', () => {
    expect(addUsage(undefined, undefined)).toBeUndefined();
  });
});
EOF
cat >> src/orchestration/orchestratorHelpers.ts <<'EOF'

/** Adds two rounds' usage field by field; a round that reported nothing contributes nothing, and two that reported nothing stay `undefined`. */
export function addUsage(total: UsageMetadata | undefined, round: UsageMetadata | undefined): UsageMetadata | undefined {
  if (!total || !round) return total ?? round;
  return {
    inputTokens: total.inputTokens + round.inputTokens,
    outputTokens: total.outputTokens + round.outputTokens,
    totalTokens: total.totalTokens + round.totalTokens,
  };
}
EOF
